"""Redacted copy of every Claude Code session -> out/<project>/<session>.jsonl"""
import glob, json, os, re, sys
sys.path.insert(0, "/Users/aman/Developer/footprint")
from footprint_core.memory import _redact
out = sys.argv[1]
EXTRA = [re.compile(r"tvly-[A-Za-z0-9_-]{8,}"), re.compile(r"fp_[A-Za-z0-9_-]{12,}"),
         re.compile(r"[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}"),          # emails
         re.compile(r"(?<!\d)(?:\+?91[\s-]?)?[6-9]\d{9}(?!\d)"),                  # Indian mobile numbers
         re.compile(r"(?<!\d)\+?\d[\d\s-]{9,13}\d(?!\d)(?=\D*(?:phone|mobile|call))", re.I)]
def red(s):
    s = _redact(s)
    for p in EXTRA:
        s = p.sub("[redacted]", s)
    return s
def walk(o):
    if isinstance(o, dict):
        if o.get("type") == "image" or (o.get("type") == "base64" and "data" in o):
            return {"type": "text", "text": "[image removed]"}
        return {k: walk(v) for k, v in o.items()}
    if isinstance(o, list):
        return [walk(x) for x in o]
    return red(o) if isinstance(o, str) else o
n = 0
for f in glob.glob(os.path.expanduser("~/.claude/projects/*/*.jsonl")):
    proj = f.split("/")[-2].replace("-Users-aman-Developer-", "").strip("-") or "home"
    dst = os.path.join(out, proj, os.path.basename(f))
    os.makedirs(os.path.dirname(dst), exist_ok=True)
    with open(f, encoding="utf-8", errors="replace") as src, open(dst, "w", encoding="utf-8") as w:
        for line in src:
            try:
                w.write(json.dumps(walk(json.loads(line)), ensure_ascii=False) + "\n")
            except json.JSONDecodeError:
                pass
    n += 1
print(n, "sessions exported")
EOF
